    b_fc_ptrs = b_fc_ptr + offset_wn
    b_g = tl.load(b_g_ptrs, mask=offset_wn < N, other=0.0)
    b_fc = tl.load(b_fc_ptrs, mask=offset_wn < N, other=0.0)

    accumulator_g = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)
